run_script %{"script" => "local result, err = create_issue({
  title = "Reservations spec missing Test Assertions section",
  description = "The spec for the Reservations component does not include a Test Assertions section. Every component spec is expected to document the assertions its tests verify; without this section, it's unclear what behavior the spec commits Reservations to testing. Add a Test Assertions section to the Reservations spec enumerating the expected test assertions.",
  severity = "warning",
  scope = "app"
})
if result == nil then return { ok = false, error = err.message } end
return { ok = true, issue = result }"}

